import {recoveredModel} from './dorf-materials.js?v=1';
import * as T from 'three';import{OrbitControls}from './vendor/OrbitControls.js';import{OBJLoader}from './vendor/OBJLoader.js';
const $=id=>document.getElementById(id),host=$('scene'),status=$('scene-status');host.classList.add('dorf-workbench');
document.querySelector('.scene-note small').textContent='DORFROMANTIK · ASSET WORKBENCH';document.querySelector('.scene-note h1').textContent='Models, layouts & tile maker';document.querySelector('.scene-note p').textContent='Extracted game artwork. Recovered material IDs, painted textures and ink masks. Browser lighting study.';
for(const id of ['tree-view','barn-view'])$(id).hidden=true;document.querySelector('.scene-tools a').hidden=true;$('home-view').textContent='Fit';
const css=document.createElement('link');css.rel='stylesheet';css.href='/dorf-workbench.css?v=2';document.head.append(css);
const pane=document.createElement('aside');pane.id='dorf-panel';pane.setAttribute('aria-label','Dorfromantik workbench');pane.innerHTML=`<div class="wb-head"><strong>Workbench</strong><button id="wb-close" aria-label="Close workbench">×</button></div><div class="wb-tabs" role="group" aria-label="Workbench section"><button data-mode="models" aria-pressed="true">Models</button><button data-mode="prefabs">Prefabs</button><button data-mode="maker">Maker</button></div><div id="wb-content"></div><section class="wb-review"><label for="review-note">Review notes</label><textarea id="review-note" rows="2" placeholder="What should we learn from this?"></textarea><button id="save-study">Save study</button><button id="export-study">Export JSON</button><button id="load-study">Load saved study</button><p id="save-status" role="status">Saved on this browser only.</p></section>`;host.append(pane);
const opener=document.createElement('button');opener.id='wb-open';opener.textContent='Workbench';opener.setAttribute('aria-expanded','false');document.querySelector('.scene-tools').prepend(opener);const open=()=>{pane.classList.add('open');opener.setAttribute('aria-expanded','true');$('wb-close').focus();};const close=()=>{pane.classList.remove('open');opener.setAttribute('aria-expanded','false');opener.focus();};opener.onclick=open;$('wb-close').onclick=close;pane.addEventListener('keydown',e=>{if(e.key==='Escape')close();});
const scene=new T.Scene();scene.background=new T.Color('#e5e7da');const camera=new T.PerspectiveCamera(32,1,.01,300);const renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));const stage=document.createElement('div');stage.id='dorf-stage';stage.append(renderer.domElement);host.prepend(stage);renderer.domElement.setAttribute('aria-label','Interactive Dorfromantik model and tile preview');const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.minDistance=3;controls.maxDistance=160;controls.maxPolarAngle=Math.PI*.49;scene.add(new T.HemisphereLight('#fff8e4','#7a8570',2));const light=new T.DirectionalLight('#fff0d0',2);light.position.set(-20,30,25);scene.add(light);
renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.NoToneMapping;renderer.toneMappingExposure=1.15;
light.intensity=2.7;light.castShadow=true;light.shadow.mapSize.set(2048,2048);Object.assign(light.shadow.camera,{left:-25,right:25,top:25,bottom:-25,near:.5,far:100});light.shadow.bias=-.0003;light.shadow.normalBias=.025;light.shadow.radius=3;
scene.children.find(n=>n.isHemisphereLight).intensity=2.7;
let painted=true;
const materialToggle=document.createElement('button');materialToggle.textContent='Materials: recovered';materialToggle.setAttribute('aria-pressed','true');document.querySelector('.scene-tools').append(materialToggle);
materialToggle.onclick=()=>{painted=!painted;materials.forEach(m=>{if(m.userData.paint)m.userData.paint.value=painted?1:0;});materialToggle.textContent=painted?'Materials: recovered':'Materials: raw';materialToggle.setAttribute('aria-pressed',String(painted));};
const studyButton=document.createElement('button');studyButton.textContent='Village study';document.querySelector('.scene-tools').prepend(studyButton);studyButton.onclick=()=>villageStudy();
const content=new T.Group();scene.add(content);const cache=new Map(),loader=new OBJLoader(),materials=new Map();let study=false;let mode='models',selected='1022',layout='',items=[],selectedItem=0,revision=0,wire=false,tile=false,source='Extracted mesh',catalog;
const wireButton=document.createElement('button');wireButton.textContent='Wireframe';wireButton.setAttribute('aria-pressed','false');document.querySelector('.scene-tools').append(wireButton);wireButton.onclick=()=>{wire=!wire;materials.forEach(m=>m.wireframe=wire);wireButton.setAttribute('aria-pressed',String(wire));};
function resize(){renderer.setSize(stage.clientWidth,stage.clientHeight);camera.aspect=stage.clientWidth/stage.clientHeight;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(stage);renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera)});
function fit(){const b=new T.Box3().setFromObject(content);if(b.isEmpty())return;const center=b.getCenter(new T.Vector3()),size=b.getSize(new T.Vector3()),radius=size.length()/2;const fov=2*Math.atan(Math.tan(T.MathUtils.degToRad(16))*Math.min(1,camera.aspect));const distance=radius/Math.sin(fov/2)*(study?.66:tile?.88:1.15);controls.target.copy(center);camera.position.copy(center).add(new T.Vector3(1,.7,1.3).normalize().multiplyScalar(distance));controls.update();}
$('home-view').onclick=fit;$('zoom-view').onclick=()=>{camera.position.lerp(controls.target,.15);controls.update();};$('turn-view').onclick=()=>{const d=camera.position.clone().sub(controls.target).applyAxisAngle(new T.Vector3(0,1,0),Math.PI/6);camera.position.copy(controls.target).add(d);controls.update();};
async function model(id){if(cache.has(id))return cache.get(id);const meta=catalog.models.find(m=>m.id===id);const job=recoveredModel(meta,painted,wire,materials);cache.set(id,job);return job;}
async function render(shouldFit=true){const token=++revision;status.textContent='Loading study…';try{const loaded=await Promise.all(items.map(i=>model(i.model)));if(token!==revision)return;while(content.children.length){const o=content.children[0];content.remove(o);if(o.userData.base){o.geometry.dispose();o.material.dispose();}}
if(tile){const ground=new T.Mesh(new T.CylinderGeometry(12,12,.45,6),new T.MeshStandardMaterial({color:'#a7b66b',roughness:1}));ground.receiveShadow=true;ground.rotation.y=Math.PI/6;ground.position.y=-.25;ground.userData.base=true;content.add(ground);if(study)studyGround();}items.forEach((i,k)=>{const obj=loaded[k].clone(true);obj.position.fromArray(i.position);obj.quaternion.fromArray(i.quaternion||[0,0,0,1]);obj.scale.set(...(i.scale||[20,20,20]));content.add(obj);});if(shouldFit)fit();status.textContent=items.length+' pieces · '+source;}catch(e){status.textContent='Could not load this study. Choose another item to retry.';console.error(e);}}

function villageStudy(){study=true;tile=true;source='Recovered house + tree shaders · summer palette / browser lighting';
const houses=[['1022',-4,1,0],['875',0,3,.35],['957',4,1.5,-.2],['818',4,-3,.6],['771',-.5,-3,0],['985',-5,-4,.3]];
items=houses.map(([model,x,z,a])=>({model,position:[x,0,z],quaternion:[0,Math.sin(a/2),0,Math.cos(a/2)],scale:[15,15,15]}));
const trees=catalog.models.filter(m=>m.category==='Trees');const spots=[[-8,-2],[-7,1],[-7.5,4],[-5.8,5.8],[-3,6.4],[1.3,6.5],[4.8,6],[7,4],[7,-1],[6,-5],[-2,-6.5],[1,-7],[-5,-7],[-8,-4]];
spots.forEach(([x,z],k)=>{let a=k*.9,sz=13+(k%3)*2;items.push({model:trees[k%trees.length].id,position:[x,0,z],quaternion:[0,Math.sin(a/2),0,Math.cos(a/2)],scale:[sz,sz,sz]});});render();if(mode==='maker')pieceEditor();}
function studyGround(){const patch=(points,color,y=.005)=>{const shape=new T.Shape();points.forEach(([x,z],i)=>i?shape.lineTo(x,-z):shape.moveTo(x,-z));shape.closePath();const g=new T.ShapeGeometry(shape);g.rotateX(-Math.PI/2);const mat=new T.MeshLambertMaterial({color,side:T.DoubleSide});const mesh=new T.Mesh(g,mat);mesh.position.y=y;mesh.receiveShadow=true;mesh.userData.base=true;content.add(mesh);};
patch([[-11,-3],[-7,-8],[-2,-9],[0,-5],[-3,-1],[-8,0]],'#93a95e');patch([[1,-9],[6,-8],[10,-3],[8,0],[4,-2]],'#a1b765');patch([[-9,3],[-5,8],[0,10],[2,7],[-1,4]],'#b5bc6b');patch([[3,2],[8,0],[10,4],[5,8],[1,6]],'#8fa35c');
patch([[-2,-11],[-.8,-8],[1,-5],[2,-1],[1,2],[-1,5],[-.7,9],[-2,9],[-2.4,5],[-.2,1],[.4,-1],[-.5,-5],[-2.2,-8],[-3,-11]],'#c8ba8a',.015);
items.slice(0,6).forEach((i,k)=>{const [x,,z]=i.position;patch([[x-1.5,z-1.5],[x+1.5,z-1.3],[x+1.8,z+1],[x+.8,z+1.7],[x-1.6,z+1.2]],k%2?'#b9af87':'#c5b495',.012);});}
function options(category){return catalog.models.filter(m=>!category||m.category===category).map(m=>`<option value="${m.id}">${m.name.replaceAll('_',' ')}</option>`).join('');}
function single(){study=false;tile=false;source='Extracted mesh';items=[{model:selected,position:[0,0,0],quaternion:[0,0,0,1],scale:[20,20,20]}];render();}
function prefab(){study=false;const p=catalog.prefabs.find(p=>p.id===layout);if(!p)return;tile=true;source='Recovered layout / preview model choices';const pool=catalog.models.filter(m=>m.category===p.category);items=p.items.map((v,i)=>({model:pool[i%pool.length].id,position:[-v.position[0]*20,v.position[1]*20,v.position[2]*20],quaternion:[v.quaternion[0],-v.quaternion[1],-v.quaternion[2],v.quaternion[3]],scale:v.scale.map(s=>s*20)}));render();}
function seeded(n){return()=>{n=(Math.imul(n,1664525)+1013904223)>>>0;return n/4294967296;};}
function generate(){study=false;const seed=+$('maker-seed').value||1,r=seeded(seed),count=+$('maker-count').value;tile=true;source='New procedural arrangement · seed '+seed;const pool=catalog.models.filter(m=>m.category===($('maker-theme').value));items=[];for(let k=0;k<count;k++){let pos;for(let tries=0;tries<250;tries++){let a=r()*Math.PI*2,rr=Math.sqrt(r())*8.6;pos=[Math.cos(a)*rr,0,Math.sin(a)*rr];if(items.every(i=>Math.hypot(pos[0]-i.position[0],pos[2]-i.position[2])>2.6))break;}let angle=Math.floor(r()*6)*Math.PI/3,s=13+r()*5;items.push({model:pool[Math.floor(r()*pool.length)].id,position:pos,quaternion:[0,Math.sin(angle/2),0,Math.cos(angle/2)],scale:[s,s,s]});}selectedItem=0;render();pieceEditor();}
function pieceEditor(){const el=$('piece-editor');if(!el)return;el.innerHTML=`<label>Selected piece<select id="piece-select">${items.map((i,k)=>`<option value="${k}">${k+1}. ${catalog.models.find(m=>m.id===i.model)?.name||i.model}</option>`).join('')}</select></label><div class="wb-grid"><label>East / west<input id="piece-x" type="number" step=".5" min="-11" max="11"></label><label>North / south<input id="piece-z" type="number" step=".5" min="-11" max="11"></label></div><button id="piece-turn">Rotate 60°</button><button id="piece-delete">Remove piece</button>`;if(!items.length)return;selectedItem=Math.min(selectedItem,items.length-1);$('piece-select').value=selectedItem;const sync=()=>{$('piece-x').value=items[selectedItem].position[0].toFixed(2);$('piece-z').value=items[selectedItem].position[2].toFixed(2);};sync();$('piece-select').onchange=()=>{selectedItem=+$('piece-select').value;sync();};for(const axis of ['x','z'])$('piece-'+axis).onchange=()=>{items[selectedItem].position[axis==='x'?0:2]=Math.max(-11,Math.min(11,+$('piece-'+axis).value||0));render(false);};$('piece-turn').onclick=()=>{const q=new T.Quaternion().fromArray(items[selectedItem].quaternion);q.multiply(new T.Quaternion().setFromAxisAngle(new T.Vector3(0,1,0),Math.PI/3));items[selectedItem].quaternion=q.toArray();render(false);};$('piece-delete').onclick=()=>{items.splice(selectedItem,1);selectedItem=0;pieceEditor();render(false);};}
let assetCategory='All';const thumbnails=new Map();let thumbRenderer;
function readableName(m){return m.name.replace(/_simplified_v002|_v00[12]|_Inverted_joined_v001/g,'').replaceAll('_',' ');}
async function thumbnail(id){if(thumbnails.has(id))return thumbnails.get(id);const obj=(await model(id)).clone(true);if(!thumbRenderer){thumbRenderer=new T.WebGLRenderer({antialias:true,alpha:true});thumbRenderer.setSize(160,128);thumbRenderer.setPixelRatio(1);thumbRenderer.toneMapping=renderer.toneMapping;thumbRenderer.toneMappingExposure=renderer.toneMappingExposure;}
const sc=new T.Scene();sc.background=new T.Color('#e6e9dd');sc.add(obj);sc.add(new T.HemisphereLight('#fff8e4','#7a8570',2.7));const sun=new T.DirectionalLight('#fff0d0',2.7);sun.position.set(-2,3,2.5);sc.add(sun);const box=new T.Box3().setFromObject(obj),center=box.getCenter(new T.Vector3()),r=box.getSize(new T.Vector3()).length()/2;const cam=new T.PerspectiveCamera(32,1.25,.001,100);cam.position.copy(center).add(new T.Vector3(1,.7,1.3).normalize().multiplyScalar(r/Math.sin(T.MathUtils.degToRad(16))*1.12));cam.lookAt(center);thumbRenderer.render(sc,cam);const url=thumbRenderer.domElement.toDataURL('image/png');thumbnails.set(id,url);return url;}
function drawRail(){const rail=$('asset-rail');if(!rail)return;const query=$('asset-search').value.toLowerCase();const list=catalog.models.filter(m=>(assetCategory==='All'||m.category===assetCategory)&&readableName(m).toLowerCase().includes(query));$('asset-count').textContent=list.length+' models · tap to inspect';rail.innerHTML=list.map(m=>`<button class="asset-card" data-asset="${m.id}" aria-pressed="${selected===m.id}" aria-label="Inspect ${readableName(m)}"><span class="asset-thumb"><img alt="" width="96" height="77"></span><span class="asset-copy"><strong>${readableName(m)}</strong><small>${m.category} · ${m.vertices} vertices</small></span><span class="asset-arrow">↗</span></button>`).join('')||'<p>No models match. Try another name.</p>';
rail.querySelectorAll('[data-asset]').forEach(b=>{b.onclick=()=>{selected=b.dataset.asset;rail.querySelectorAll('[data-asset]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));single();};thumbnail(b.dataset.asset).then(url=>{if(b.isConnected)b.querySelector('img').src=url;}).catch(()=>{if(b.isConnected)b.querySelector('.asset-thumb').textContent='Preview unavailable';});});}
function panel(){document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));const el=$('wb-content');if(mode==='models'){
el.innerHTML=`<div class="asset-pills" role="group" aria-label="Asset categories">${['All','Houses','Trees','Fields','Terrain'].map(c=>`<button data-category="${c}" aria-pressed="${c===assetCategory}">${c}</button>`).join('')}</div><label class="asset-search">Find an asset<input id="asset-search" type="search" placeholder="Search models…" value=""></label><div class="asset-summary" id="asset-count"></div><div id="asset-rail" aria-label="Model library"></div><button id="add-model">Add selected to maker ↗</button><p class="asset-disclaimer">House masks + tree outline shader recovered. Summer tree colors and lighting are a browser study.</p>`;
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{assetCategory=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));drawRail();});
$('asset-search').oninput=drawRail;
$('add-model').onclick=()=>{items.push({model:selected,position:[0,0,0],quaternion:[0,0,0,1],scale:[16,16,16]});tile=true;source='User assembly';mode='maker';panel();render();};drawRail();}

else if(mode==='prefabs'){el.innerHTML=`<p>${catalog.prefabs.length} recovered segment layouts. Positions, rotations and scales come from the game; model choices are preview substitutions.</p><label>Saved game layout<select id="prefab-select">${catalog.prefabs.map(p=>`<option value="${p.id}">${p.name} · ${p.items.length} pieces</option>`).join('')}</select></label><button id="inspect-prefab">Load layout</button><button id="edit-prefab">Edit in maker</button><p>These are segment arrangements, not a reconstruction of the full runtime tile system.</p>`;if(layout)$('prefab-select').value=layout;$('inspect-prefab').onclick=()=>{layout=$('prefab-select').value;prefab();};$('edit-prefab').onclick=()=>{layout=$('prefab-select').value;prefab();mode='maker';panel();};}
else{el.innerHTML=`<p>Compose extracted pieces on a new hex base. This maker is ours, not Dorfromantik’s generation algorithm.</p><div class="wb-grid"><label>Seed<input id="maker-seed" type="number" value="41" min="1" max="999999"></label><label>Pieces<input id="maker-count" type="number" value="7" min="1" max="18"></label></div><label>Collection<select id="maker-theme"><option>Houses</option><option>Trees</option></select></label><button id="generate">Generate tile</button><button id="variation">New seed</button><div id="piece-editor"></div>`;$('generate').onclick=()=>{$('maker-count').value=Math.max(1,Math.min(18,+$('maker-count').value||7));generate();};$('variation').onclick=()=>{$('maker-seed').value=+$('maker-seed').value+1;$('generate').click();};pieceEditor();}}
const snapshot=()=>({version:1,source,mode,selected,layout,tile,study,items,notes:$('review-note').value,savedAt:new Date().toISOString()});$('save-study').onclick=()=>{try{localStorage.setItem('dorf-workbench-study-v1',JSON.stringify(snapshot()));$('save-status').textContent='Study and notes saved in this browser.';}catch{$('save-status').textContent='Saving unavailable. Export JSON to keep a copy.';}};$('export-study').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='dorfromantik-study.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('load-study').onclick=()=>{try{const s=JSON.parse(localStorage.getItem('dorf-workbench-study-v1'));if(!s||s.version!==1||!Array.isArray(s.items))throw Error();items=s.items.filter(i=>catalog.models.some(m=>m.id===i.model));tile=s.tile;study=!!s.study;source=s.source;mode='maker';$('review-note').value=s.notes||'';panel();render();$('save-status').textContent='Saved study restored.';}catch{$('save-status').textContent='No saved study found in this browser.';}};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;panel();});
try{catalog=await(await fetch('/reference-assets/dorfromantik/catalog.json')).json();panel();resize();villageStudy();}catch(e){status.textContent='Catalog could not load. Reload to retry.';console.error(e);}

window.RanchView?.register('dorfromantik',()=>({mode,selectedModel:selected,selectedLayout:layout,selectedItem,items,wireframe:wire,tile,source,revision,camera:{position:camera.position.toArray(),target:controls.target.toArray(),fov:camera.fov}}),()=>renderer.render(scene,camera));
controls.addEventListener('end',()=>window.RanchView?.changed());